-- Initialize working CITY_SUPPORT only. Immutable snapshots and serving HTML stay untouched.
BEGIN;
LOCK TABLE "Site", "Page", "PageTemplate", "PageTemplateBlock", "SeoTemplate", "ContentRevision", "AuditEvent" IN SHARE ROW EXCLUSIVE MODE;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='Page_support_scope_check') THEN ALTER TABLE "Page" ADD CONSTRAINT "Page_support_scope_check" CHECK ("type" <> 'CITY_SUPPORT' OR ("cityId" IS NOT NULL AND slug='tehpodderzhka' AND "templateId" IS NOT NULL)); END IF; END $$;
CREATE UNIQUE INDEX IF NOT EXISTS "Page_support_city_key" ON "Page" ("cityId") WHERE type='CITY_SUPPORT';
CREATE TEMP TABLE _support_sites ON COMMIT DROP AS SELECT s.id,s."workingRevision"+1 AS revision FROM "Site" s JOIN "Provider" p ON p.id=s."providerId" WHERE p.slug='domru' AND NOT EXISTS (SELECT 1 FROM "PageTemplate" t WHERE t."siteId"=s.id AND t.kind='CITY_SUPPORT');
DO $$ BEGIN IF EXISTS (SELECT 1 FROM "Page" p JOIN _support_sites s ON s.id=p."siteId" WHERE p."cityId" IS NOT NULL AND p.slug='tehpodderzhka') OR EXISTS (SELECT 1 FROM "Tariff" t JOIN "City" c ON c.id=t."cityId" JOIN _support_sites s ON s.id=c."siteId" WHERE t.slug='tehpodderzhka') OR EXISTS (SELECT 1 FROM "Redirect" r JOIN "City" c ON r."siteId"=c."siteId" AND r."sourcePath"='/'||c.slug||'/tehpodderzhka' JOIN _support_sites s ON s.id=c."siteId") THEN RAISE EXCEPTION 'CITY_SUPPORT canonical URL collision; preserve authored rows and resolve explicitly'; END IF; END $$;
CREATE TEMP TABLE _support_content ON COMMIT DROP AS SELECT s.id AS "siteId", $support${"version":"1.0.0","hero":{"h1":"Техническая поддержка Дом.ру в {CITY_NAME_PREPOSITIONAL}","intro":"Выберите нужный отдел: подключение или поддержка.","connection":{"title":"Подключение","audience":"Для новых абонентов","topics":{"one":"Оформление подключения","two":"Проверка адреса","three":"Подбор интернета и ТВ"},"label":"Телефон отдела подключений в {CITY_NAME_PREPOSITIONAL}"},"support":{"title":"Техническая поддержка","audience":"Для действующих абонентов","topics":{"one":"Не работает интернет или ТВ","two":"Оплата и баланс","three":"Настройка оборудования"},"label":"Телефон технической поддержки в {CITY_NAME_PREPOSITIONAL}","freeCall":"Бесплатный звонок по России"}},"quickLinks":{"hotline":"Горячая линия 8-800","cityPhones":"Городские телефоны","callback":"Обратный звонок","chat":"Онлайн-чат","social":"Соцсети","account":"Личный кабинет","app":"Приложение"},"introduction":{"first":"Если вы уже являетесь или хотите стать абонентом Дом.ру, то иногда вам придется обращаться в службу технической поддержки провайдера. Причины обращений могут быть разными. Например, техническая неисправность wi-fi роутера или тв-приставки, требование подключить новый пакет каналов или увеличить скорость интернета.","second":"Сотрудники контакт-центра компании проконсультируют по любым вопросам и помогут решить возникшие проблемы. **Техническая поддержка Дом.ру работает круглосуточно.** Связаться со специалистами поддержки можно несколькими способами:","image":{"src":"/images/support/v1/introduction-3928f4daecce4a9d1ce95787.png","alt":"Оператор технической поддержки Дом.ру","caption":"Оператор технической поддержки Дом.ру","assetId":"","crop":{"x":0,"y":0,"width":1,"height":1}}},"address":{},"phones":{"title":"Телефоны Дом.ру","hotlineTitle":"Телефон горячей линии Дом.ру 8-800","numberIntro":"Бесплатный номер технической поддержки абонентов кабельного телевидения и интернета Дом.ру:","numberNote":"Этот номер телефона работает круглосуточно, и звонки на него бесплатны на всей территории России.","connectionTitle":"Связь со специалистом","connectionBody":"Перед соединением со специалистом поддержки автоинформатор информационного центра Дом.ру сообщает абонентам о состоянии баланса лицевого счета, а также информирует о профилактических и ремонтных работах.","skipMenu":"Чтобы не слушать голосовое меню и сразу перейти к общению со специалистом, нажмите клавишу **0 (ноль)**.","helpTitle":"С чем поможет поддержка","helpBody":"Служба поддержки [Дом.ру](home) помогает действующим абонентам в ситуациях, когда услуги уже подключены: появились проблемы с домашним интернетом или ТВ, нужна настройка оборудования, диагностика линии и требуется оформить выезд мастера.","newConnection":{"title":"Для нового подключения","body":"По вопросам [подключения услуг интернета](address) и цифрового телевидения (проверка адреса, подбор тарифа, оформление заявки) обращайтесь по телефону отдела подключений [{CONNECTION_PHONE}](connection-phone)."},"cityTitle":"Городские телефоны поддержки Дом.ру","cityIntro":"Дом.ру работает в более чем 100 [городах](cities) по всей России, и в каждом населенном пункте у провайдера есть местные контактные номера для бесплатных звонков на горячую линию. Обращаясь на городской номер провайдера, вы гарантированно получите оперативную и квалифицированную помощь.","official":{"title":"На официальном сайте","body":"После входа на [официальный сайт](official) ваш город определяется автоматически. Городской номер службы поддержки отобразится в правом верхнем углу экрана."},"account":{"title":"В личном кабинете","body":"Также номер техподдержки вашего города отображается в личном кабинете в разделе «Помощь»."},"cost":{"title":"Оплата звонка","body":"Звонки на такие номера оплачиваются по тарифам на услуги вашего мобильного оператора. Чтобы не тратить деньги, вы можете заказать обратный звонок от оператора Дом.ру на сайте."},"image":{"src":"/images/support/v1/phone-96eb76c738cb3b1f4e9384c0.png","alt":"Телефон технической поддержки Дом ру в Казани","caption":"Телефон технической поддержки Дом ру в Казани","assetId":"","crop":{"x":0.7202295552367288,"y":0,"width":0.23242467718794835,"height":0.08477842003853564}},"zoomCaption":"Номер на скриншоте — крупно","exampleNote":"На фото изображен пример контактного номер Дом.ру для города Казань."},"callback":{"title":"Как заказать обратный звонок от оператора?","intro":"Если у вас нет возможности позвонить самостоятельно или вы предпочитаете, чтобы вам перезвонили в удобное время — оставьте заявку на обратный звонок через специальную форму на сайте Дом.ру.","steps":{"step1":"Для этого на сайте найдите раздел «Помощь», он находится в верхнем правом углу.","step2":"В списке выберите пункт «Наши контакты». После этого откроется страница со всеми способами связи с технической поддержкой, найдите форму «Закажите обратный звонок».","step3":"Укажите ваш контактный номер телефона и имя, после чего нажмите кнопку «Позвоните мне»."},"explanation":"Специалисты провайдера оперативно свяжутся с вами, предоставят всю необходимую информацию и помогут решить возникшие проблемы. Эта услуга удобна для тех, кто ценит свое время и хочет получить помощь без долгого ожидания на линии.","appNote":"Отметим, что заявку на обратный звонок можно оформить в мобильном приложении «Мой Дом.ру».","menu":{"src":"/images/support/v1/callbackmenu-029126b2cafde1baabc881a7.png","alt":"Меню раздела помощь на сайте Дом.ру","caption":"Меню раздела помощь на сайте Дом.ру","assetId":"","crop":{"x":0.3205397444237455,"y":0.062461683355693964,"width":0.443285499133931,"height":0.40069658548721004}},"form":{"src":"/images/support/v1/callbackform-5d45af31654b989b701622b9.png","alt":"Форма заказа обратного звонка от Дом ру","caption":"Форма заказа обратного звонка от Дом ру","assetId":"","crop":{"x":0.0039958654865492,"y":0.7000186465157879,"width":0.49227816520450185,"height":0.2819843053224741}}},"chat":{"title":"Онлайн-консультация в чате Дом.ру","intro":"Решить несложные типовые вопросы проще всего в формате онлайн-чата, избежав ожидания на телефонной линии.","entryText":"Значок чата для онлайн-консультации размещен на каждой странице официального сайта в правом нижнем углу. Нажмите красную круглую кнопку, чтобы открыть окно для переписки.","entry":{"src":"/images/support/v1/chatentry-d948e16f0a56eb23dbb608ca.png","alt":"Иконка чата на сайте","caption":"Иконка чата на сайте","assetId":"","crop":{"x":0.3974658591037166,"y":0.6358643852403214,"width":0.6025341408962834,"height":0.3641356147596786}},"dialogue":"Диалог с вами начнет робот-помощник, он может самостоятельно ответить на большинство вопросов, но при необходимости переведет диалог на живого человека.","image":{"src":"/images/support/v1/chatdialogue-fafd16d2e12dbbf5d665f7db.png","alt":"Окно для переписки","caption":"Окно для переписки","assetId":"","crop":{"x":0.6450704225352113,"y":0.24040066777963273,"width":0.3474178403755869,"height":0.7595993322203672}}},"social":{"title":"Поддержка и сообщества Дом.ру","intro":"Вопрос по услугам Дом.ру можно задать в сообщениях сообщества ВКонтакте. В Одноклассниках и Telegram компания публикует новости и полезные материалы.","vk":{"title":"ВКонтакте — поддержка","body":"Задайте вопрос в сообщениях сообщества.","label":"Написать ВКонтакте","href":"https://vk.me/domru"},"newsTitle":"Новости и сообщества Дом.ру","ok":{"title":"Одноклассники","body":"Новости и публикации компании.","label":"Открыть сообщество","href":"https://ok.ru/domru"},"telegram":{"title":"Telegram","body":"Новости, технологии и кино.","label":"Открыть канал","href":"https://t.me/domru_official"},"image":{"src":"/images/support/v1/social-069c4ed1610673e35a9d7fbb.png","alt":"Официальное сообщество Дом.ру Вконтакте","caption":"Официальное сообщество Дом.ру Вконтакте","assetId":"","crop":{"x":0,"y":0,"width":1,"height":1}}},"account":{"title":"Техническая поддержка в личном кабинете Дом.ру","intro":"Ещё один удобный способ получить помощь — оставить заявку прямо из личного кабинета. В этом случае специалисты смогут быстро получить всю необходимую информацию о вашем лицевом счете, подключенных услугах и тарифах.","instruction":"Для связи с техподдержкой через [личный кабинет](account):","steps":{"step1":"Авторизуйтесь в личном кабинете по адресу электронной почты, телефону или номеру договора.","step2":"В верхнем правом углу нажмите круглую кнопку с силуэтом человека и перейди по ссылке «Обращения в поддержку».","step3":"После этого откроется страница с полной историей обращений в техподдержку из вашего личного кабинет. Нажмите кнопку «Создать новое обращение».","step4":"В открывшемся окне выберете типовую проблему и опишите её подробнее, укажите ваши контактные данные и нажмите «Создать обращение»"},"image":{"src":"/images/support/v1/account-ae00e0dcc92620e8d6e26468.png","alt":"Обращение в поддержку в ЛК Дом.ру","caption":"Обращение в поддержку в ЛК Дом.ру","assetId":"","crop":{"x":0,"y":0,"width":1,"height":1}}},"app":{"title":"Онлайн-консультация в приложении Мой Дом.ру","intro":"Удобное мобильное приложение «Мой Дом.ру» для Android также позволяет легко связаться со службой поддержки.","body":"Войдите в приложение под своей учетной записью и выберите «Помощь» в нижнем меню. В этом разделе доступны несколько инструментов — онлайн-чат, диагностика неполадок, [тест скорости интернета](speed). Кроме того здесь размещена полезная база ответов на [популярные вопросы](faq), которая поможет решить проблему самостоятельно.","image":{"src":"/images/support/v1/app-ebba0b7b3ccd1ae560d57b38.jpg","alt":"Экран приложения Мой Дом.ру","caption":"Экран приложения Мой Дом.ру","assetId":"","crop":{"x":0,"y":0,"width":1,"height":1}},"stores":{"googlePlay":"https://play.google.com/store/apps/details?id=com.ertelecom.agent&hl=ru","ruStore":"https://www.rustore.ru/catalog/app/com.ertelecom.agent","appGallery":"https://appgallery.huawei.com/app/C101960911"}},"capabilities":{"title":"Как работает поддержка и чем может помочь","remoteTitle":"Удаленная поддержка от специалистов Дом.ру","remoteIntro":"Если проблему не получится решить дистанционно, то к решения подключаются эксперты техподдержки Дом.ру. После вашего согласия они получают временный удаленный доступ к вашему оборудованию для проведения диагностики.","consent":"Доступ является безопасным и осуществляется только по вашему согласию. Личные данные при этом останутся конфиденциальными.","stepsTitle":"Инструкция удаленного доступа:","steps":{"step1":"Обратитесь в техподдержку обычным способом — по телефону, в чате или через заявку","step2":"Подробно опишите суть проблемы","step3":"Если оператор не сможет решить ее сразу, он предложит удаленную помощь эксперта","step4":"Вам будет выслана ссылка на установку приложения для получения удаленного доступа","step5":"После запуска приложения введите код доступа, который продиктует оператор","step6":"Удаленный специалист сможет управлять вашим оборудованием со своего рабочего места","step7":"Следуйте инструкциям оператора для решения проблемы"},"competenceTitle":"Компетентность специалистов провайдера","training":{"title":"Подготовка специалистов","body":"Все операторы и инженеры технической поддержки Дом.ру проходят серьезную многоуровневую подготовку. Они изучают все нюансы услуг и оборудования провайдера, программного обеспечения и способы решения сложных проблем у абонентов."},"approach":{"title":"Подход к работе","body":"В работе специалисты руководствуются главными принципами — вежливое и клиентоориентированное отношение, внимание к деталям, стремление найти оптимальное решение. Богатый практический опыт операторов и мастеров позволяет быстро справляться с большинством задач."},"limitsTitle":"В каких случаях операторы Дом.ру не смогут помочь?","limitsIntro":"Следует понимать, что техническая поддержка провайдера может помочь не во всех случаях. К сожалению, есть ситуации, в которых операторы Дом.ру будут бессильны:","limits":{"data":{"title":"Данные","body":"**Восстановление утраченных данных** на локальных накопителях (жестких дисках, флешках и т. д.). За сохранность важной информации отвечает сам пользователь."},"software":{"title":"Стороннее ПО","body":"**Настройка и устранение неполадок** в работе стороннего программного обеспечения (кроме программ, предоставляемых Дом.ру). Например, проблемы с офисными пакетами, играми и пр."},"hardware":{"title":"Поломки оборудования","body":"**Физические поломки или повреждения оборудования** (ПК, роутера и другой техники). В таких случаях д ля ремонта лучше обратиться в специализированные сервисные центры."},"security":{"title":"Вирусы и атаки","body":"**Нарушения в работе оборудования и софта** из-за вирусов или хакерских атак. Дом.ру не отвечает за кибербезопасность локальной сети абонента."}},"note":"Если причина проблемы выходит за рамки компетенции сотрудников провайдера, операторы будут максимально подробно консультировать по дальнейшим действиям и возможным путям решения. Но самостоятельно исправить ситуацию они не смогут."},"business":{"title":"Бесплатная горячая линия Дом.ру для корпоративных клиентов","intro":"Для корпоративных клиентов в Дом.ру предусмотрена отдельная бесплатная круглосуточная горячая линия:","body":"Операторы горячей линии для юрлиц обладают расширенной экспертизой по всем корпоративным тарифам и услугам компании. Они оперативно реагируют на обращения, учитывают специфику и важность бесперебойной работы корпоративных сетей.","note":"Звонки на данный номер со всех регионов России абсолютно бесплатны. Линия работает круглосуточно 365 дней в году без выходных и перерывов.","image":{"src":"/images/support/v1/business-734271a567ea7bc8a3fd98df.png","alt":"Дом.ру для бизнеса","caption":"Дом.ру для бизнеса","assetId":"","crop":{"x":0,"y":0,"width":1,"height":1}}},"faq":{"title":"Популярные вопросы","items":[{"question":"Куда звонить для подключения интернета и ТВ Дом.ру в {CITY_NAME_PREPOSITIONAL}?","answer":"Для подключения позвоните по номеру {CONNECTION_PHONE}. Приём звонков: {CONNECTION_HOURS}. Если вы уже пользуетесь услугами и нужна помощь, обратитесь в поддержку: {SUPPORT_PHONE}."},{"question":"Как оставить заявку на подключение Дом.ру?","answer":"Нажмите «Оставить заявку» или «Подключить» у выбранного тарифа и укажите телефон. Онлайн-заявки принимаются: {ONLINE_APPLICATIONS_HOURS}. Срок обратного звонка — {CALLBACK_WITHIN_MINUTES} минут. Чтобы отдельно проверить дом, воспользуйтесь проверкой адреса."},{"question":"Можно ли подключить только интернет?","answer":"Выберите в каталоге категорию «Домашний интернет»: она показывает предложения без телевидения. Доступность подключения по вашему адресу можно проверить отдельно; условия выбранного предложения уточнит оператор."},{"question":"Какой самый доступный тариф в {CITY_NAME_PREPOSITIONAL}?","answer":"Минимальная стоимость среди опубликованных тарифов города — {CITY_MIN_PRICE} ₽ в месяц. Посмотрите состав предложения, срок акции и последующую цену в карточке тарифа."},{"question":"Какая максимальная скорость доступна в тарифах Дом.ру?","answer":"В опубликованных тарифах города максимальная заявленная скорость — {CITY_MAX_SPEED} Мбит/с. Доступность конкретного тарифа зависит от адреса подключения."},{"question":"Сколько цифровых каналов входит в пакеты с ТВ?","answer":"В опубликованных пакетах города с телевидением — до {CITY_MAX_CHANNELS} каналов. Точное количество и состав включённых подписок указаны в карточке выбранного тарифа."}]}}$support$::jsonb AS data FROM _support_sites s;
-- Reuse authored CITY_HOME answers for the same questions, as approved by the owner.
UPDATE _support_content s SET data=jsonb_set(s.data,'{faq,items}',(SELECT jsonb_agg(jsonb_set(q.item,'{answer}',coalesce((SELECT to_jsonb(replace(replace(replace(replace(replace(replace(a.item->>'answer','\','\\'),'*','\*'),'[','\['),']','\]'),'(','\('),')','\)')) FROM "PageTemplate" t JOIN "PageTemplateBlock" b ON b."templateId"=t.id CROSS JOIN LATERAL jsonb_array_elements(b.data->'items') a(item) WHERE t."siteId"=s."siteId" AND t.kind='CITY_HOME' AND b."blockType"='city.faq' AND a.item->>'question'=q.item->>'question' LIMIT 1),q.item->'answer')) ORDER BY q.ordinality) FROM jsonb_array_elements(s.data#>'{faq,items}') WITH ORDINALITY q(item,ordinality)));
INSERT INTO "PageTemplate" (id,"siteId",kind,status,"titleTemplate",content,"createdAt","updatedAt") SELECT 'support_template_'||md5(s."siteId"),s."siteId",'CITY_SUPPORT','PUBLISHED',s.data#>>'{hero,h1}',jsonb_build_object('supportVersion','1.0.0'),CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM _support_content s;
INSERT INTO "PageTemplateBlock" (id,"templateId","blockType",position,visible,data,source) SELECT 'support_block_'||md5(s."siteId"||k.key),'support_template_'||md5(s."siteId"),'support.'||k.key,k.ordinality*10,true,s.data->k.key,'migration:0076:support' FROM _support_content s CROSS JOIN unnest(ARRAY['hero','quickLinks','introduction','address','phones','callback','chat','social','account','app','capabilities','business','faq']) WITH ORDINALITY k(key,ordinality);
INSERT INTO "Page" (id,"siteId","cityId",type,slug,status,title,"templateId","createdAt","updatedAt") SELECT 'support_page_'||md5(c.id),c."siteId",c.id,'CITY_SUPPORT','tehpodderzhka','PUBLISHED',t."titleTemplate",t.id,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM "City" c JOIN _support_sites s ON s.id=c."siteId" JOIN "PageTemplate" t ON t."siteId"=s.id AND t.kind='CITY_SUPPORT';
INSERT INTO "SeoTemplate" (id,"siteId",kind,"titleTemplate","descriptionTemplate","indexState","createdAt","updatedAt") SELECT 'support_seo_'||md5(s.id),s.id,'CITY_SUPPORT','Техническая поддержка Дом.ру в {CITY_NAME_PREPOSITIONAL}','Телефоны и способы связи с поддержкой Дом.ру в {CITY_NAME_PREPOSITIONAL}: горячая линия, городской номер, официальный чат, личный кабинет и приложение.','INDEX',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM _support_sites s ON CONFLICT ("siteId",kind) DO NOTHING;
UPDATE "Site" s SET "workingRevision"=a.revision,"updatedAt"=CURRENT_TIMESTAMP FROM _support_sites a WHERE a.id=s.id;
INSERT INTO "ContentRevision" (id,"siteId","entityType","entityId","entityRevision","siteRevision",action,snapshot,"changedFields",source,"createdAt") SELECT 'support_revision_'||md5(t.id),t."siteId",'PAGE_TEMPLATE',t.id,1,s.revision,'CREATE',to_jsonb(t)||jsonb_build_object('blocks',(SELECT jsonb_agg(to_jsonb(b) ORDER BY b.position) FROM "PageTemplateBlock" b WHERE b."templateId"=t.id)),'["content","blocks","titleTemplate"]'::jsonb,'migration:0076:support',CURRENT_TIMESTAMP FROM "PageTemplate" t JOIN _support_sites s ON s.id=t."siteId" WHERE t.kind='CITY_SUPPORT';
INSERT INTO "AuditEvent" (id,"siteId","siteRevision","entityType","entityId",action,"changedFields",changes,source,"createdAt") SELECT 'support_audit_'||md5(s.id),s.id,s.revision,'SITE',s.id,'UPDATE','["pages","pageTemplates","seoTemplates"]'::jsonb,'{"initializedSupport":true,"preservedPublishedSnapshots":true}'::jsonb,'migration:0076:support',CURRENT_TIMESTAMP FROM _support_sites s;
COMMIT;
